'use client'

import * as React from 'react'
import { tv, type VariantProps } from 'tailwind-variants'
import { cn } from '../lib/utils'

const textareaVariants = tv({
  base: 'flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-all duration-200 shadow-sm',
  variants: {
    variant: {
      default: 'border-input focus-visible:ring-2',
      bottom:
        'rounded-none border-t-0 border-x-0 border-b border-input px-0 focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:border-primary shadow-none',
      glass:
        'bg-white/5 dark:bg-black/20 border-white/20 dark:border-white/10 backdrop-blur-md focus-visible:ring-white/30',
      retro:
        'border-2 border-foreground bg-background shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] dark:shadow-[2px_2px_0px_0px_rgba(255,255,255,1)] focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:translate-x-[1px] focus-visible:translate-y-[1px] focus-visible:shadow-[1px_1px_0px_0px_rgba(0,0,0,1)] dark:focus-visible:shadow-[1px_1px_0px_0px_rgba(255,255,255,1)]',
      glow: 'border-input focus-visible:ring-2 focus-visible:ring-primary/50 focus-visible:shadow-[0_0_15px_rgba(0,0,0,0.05)] dark:focus-visible:shadow-[0_0_15px_rgba(255,255,255,0.1)]',
      cyberpunk:
        'rounded-none border border-emerald-500 bg-black text-emerald-500 font-mono placeholder:text-emerald-700/80 focus-visible:border-emerald-400 focus-visible:ring-1 focus-visible:ring-emerald-400/40 shadow-[0_0_10px_rgba(16,185,129,0.15)]',
    },
  },
  defaultVariants: {
    variant: 'default',
  },
})

export interface TextareaProps
  extends
    React.TextareaHTMLAttributes<HTMLTextAreaElement>,
    VariantProps<typeof textareaVariants> {
  error?: boolean
}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ className, variant, error, ...props }, ref) => {
    const isInvalid = error || props['aria-invalid']
    return (
      <textarea
        data-slot="textarea"
        className={cn(
          textareaVariants({ variant }),
          isInvalid &&
            'border-destructive focus-visible:ring-destructive focus-visible:border-destructive',
          className,
        )}
        ref={ref}
        {...props}
      />
    )
  },
)
Textarea.displayName = 'Textarea'

export { Textarea }
